import { readFile, writeFile } from "node:fs/promises";

// Share model definitions while keeping provider-specific migrations separate.
const schema = await readFile(new URL("../prisma/schema.prisma", import.meta.url), "utf8");
if (!schema.includes('provider = "sqlite"') || !schema.includes('url      = "file:magicpromo-dev.sqlite"')) {
  throw new Error("Local datasource changed; review the PostgreSQL schema generator.");
}
await writeFile(new URL("../prisma/postgresql/schema.prisma", import.meta.url),
  "// Generated by npm run db:postgres:schema. Edit models in prisma/schema.prisma.\n" +
  schema.replace('provider = "sqlite"', 'provider = "postgresql"')
    .replace('url      = "file:magicpromo-dev.sqlite"', 'url      = env("DATABASE_URL")'));
